pragma solidity >=0.8.0;
contract StoragePackingProbe {
    uint8 public a;
    bool public b;
    int32 public c;
    uint8 public d;
    bytes public blob;
    uint8[4] public arr;

    event Packed(uint8 a, bool b, int32 c, uint8 d);

    function setSmall(uint8 _a, bool _b, int32 _c, uint8 _d) public {
        a = _a; b = _b; c = _c; d = _d;
        emit Packed(_a, _b, _c, _d);
    }
    function setBlob(bytes memory bl) public { blob = bl; }
    function setArr(uint256 i, uint8 v) public { arr[i] = v; }
    function clearA() public { delete a; }
}
